import pytest
from target import prime_fib


def test_prime_fib_1():
    """Test first prime Fibonacci number (boundary: minimum n)"""
    assert prime_fib(1) == 2


def test_prime_fib_2():
    """Test second prime Fibonacci number"""
    assert prime_fib(2) == 3


def test_prime_fib_3():
    """Test third prime Fibonacci number"""
    assert prime_fib(3) == 5


def test_prime_fib_4():
    """Test fourth prime Fibonacci number"""
    assert prime_fib(4) == 13


def test_prime_fib_5():
    """Test fifth prime Fibonacci number (as documented)"""
    assert prime_fib(5) == 89


def test_prime_fib_6():
    """Test sixth prime Fibonacci number (probes off-by-one beyond docstring)"""
    assert prime_fib(6) == 233


def test_prime_fib_7():
    """Test seventh prime Fibonacci number (extends pattern verification)"""
    assert prime_fib(7) == 1597
